sealed class NymAuthNativeException: kotlin.Exception() {
    
    /**
     * An argument has the wrong size, format or range, or `challenge_digest` is not the digest of
     * `transcript_seed` under DeviceAuthentication.
     */
    class InvalidInput(
        ) : NymAuthNativeException() {
        override val message
            get() = ""
    }
    
    /**
     * The circuit bytes or parameters are not the approved build they claim to be.
     */
    class InvalidCircuit(
        ) : NymAuthNativeException() {
        override val message
            get() = ""
    }
    
    /**
     * No approved build has this circuit id: this library cannot prove it.
     */
    class UnsupportedCircuit(
        ) : NymAuthNativeException() {
        override val message
            get() = ""
    }
    
    /**
     * The holder data does not fit (see [`NymAuthRefusal`]).
     */
    class Refused(
        
        val `refusal`: NymAuthRefusal
        ) : NymAuthNativeException() {
        override val message
            get() = "refusal=${ `refusal` }"
    }
    
    /**
     * The proof system failed on inputs that passed every check.
     */
    class ProverFailed(
        ) : NymAuthNativeException() {
        override val message
            get() = ""
    }
    
    /**
     * A proof does not verify.
     */
    class ProofInvalid(
        ) : NymAuthNativeException() {
        override val message
            get() = ""
    }
    
    /**
     * The proof verifies, but not for the pseudonym given.
     */
    class Mismatch(
        ) : NymAuthNativeException() {
        override val message
            get() = ""
    }
    
    /**
     * A failure of this library itself.
     */
    class Internal(
        ) : NymAuthNativeException() {
        override val message
            get() = ""
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<NymAuthNativeException> {
        override fun lift(error_buf: RustBuffer.ByValue): NymAuthNativeException = FfiConverterTypeNymAuthNativeError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeNymAuthNativeError : FfiConverterRustBuffer<NymAuthNativeException> {
    override fun read(buf: ByteBuffer): NymAuthNativeException {
        

        return when(buf.getInt()) {
            1 -> NymAuthNativeException.InvalidInput()
            2 -> NymAuthNativeException.InvalidCircuit()
            3 -> NymAuthNativeException.UnsupportedCircuit()
            4 -> NymAuthNativeException.Refused(
                FfiConverterTypeNymAuthRefusal.read(buf),
                )
            5 -> NymAuthNativeException.ProverFailed()
            6 -> NymAuthNativeException.ProofInvalid()
            7 -> NymAuthNativeException.Mismatch()
            8 -> NymAuthNativeException.Internal()
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: NymAuthNativeException): ULong {
        return when(value) {
            is NymAuthNativeException.InvalidInput -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is NymAuthNativeException.InvalidCircuit -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is NymAuthNativeException.UnsupportedCircuit -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is NymAuthNativeException.Refused -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterTypeNymAuthRefusal.allocationSize(value.`refusal`)
            )
            is NymAuthNativeException.ProverFailed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is NymAuthNativeException.ProofInvalid -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is NymAuthNativeException.Mismatch -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is NymAuthNativeException.Internal -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
        }
    }

    override fun write(value: NymAuthNativeException, buf: ByteBuffer) {
        when(value) {
            is NymAuthNativeException.InvalidInput -> {
                buf.putInt(1)
                Unit
            }
            is NymAuthNativeException.InvalidCircuit -> {
                buf.putInt(2)
                Unit
            }
            is NymAuthNativeException.UnsupportedCircuit -> {
                buf.putInt(3)
                Unit
            }
            is NymAuthNativeException.Refused -> {
                buf.putInt(4)
                FfiConverterTypeNymAuthRefusal.write(value.`refusal`, buf)
                Unit
            }
            is NymAuthNativeException.ProverFailed -> {
                buf.putInt(5)
                Unit
            }
            is NymAuthNativeException.ProofInvalid -> {
                buf.putInt(6)
                Unit
            }
            is NymAuthNativeException.Mismatch -> {
                buf.putInt(7)
                Unit
            }
            is NymAuthNativeException.Internal -> {
                buf.putInt(8)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



/**
 * Why the prover refused to make a proof for holder data that does not fit.
 */

enum class NymAuthRefusal {
    
    /**
     * `SHA-256(secret_seed)` is not the credential's `ssc`.
     */
    SEED_MISMATCH,
    /**
     * The issuer's signature on the MSO does not verify under the given issuer key.
     */
    ISSUER_SIGNATURE,
    /**
     * The device signature does not verify on `e2` under the credential's device key.
     */
    DEVICE_SIGNATURE,
    /**
     * The credential is not a nym_auth mdoc these circuits read (docType, items, issuer key).
     */
    CREDENTIAL,
    /**
     * The credential cannot meet the request: not valid at `time`, or the birth date outside `[earliest, cutoff]`.
     */
    UNSATISFIED;
    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeNymAuthRefusal: FfiConverterRustBuffer<NymAuthRefusal> {
    override fun read(buf: ByteBuffer) = try {
        NymAuthRefusal.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: NymAuthRefusal) = 4UL

    override fun write(value: NymAuthRefusal, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}






/**
 * @suppress
 */
public object FfiConverterOptionalDouble: FfiConverterRustBuffer<kotlin.Double?> {
    override fun read(buf: ByteBuffer): kotlin.Double? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterDouble.read(buf)
    }

    override fun allocationSize(value: kotlin.Double?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterDouble.allocationSize(value)
        }
    }

    override fun write(value: kotlin.Double?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterDouble.write(value, buf)
        }
    }
}
